'use strict';

// Generated by scripts/stage-vendors.js. Converts data URLs without fetch/network access.
(() => {
  const dataUrlToArrayBuffer = (dataUrl) => {
    const value = String(dataUrl || '');
    const comma = value.indexOf(',');
    if (comma <= 4 || !/^data:/iu.test(value.slice(0, comma))) throw new TypeError('data URLが不正です。');
    const metadata = value.slice(5, comma);
    const payload = value.slice(comma + 1);
    if (/;base64(?:;|$)/iu.test(metadata)) {
      const binary = atob(decodeURIComponent(payload).replace(/\s+/gu, ''));
      const bytes = new Uint8Array(binary.length);
      for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
      return bytes.buffer;
    }
    return new TextEncoder().encode(decodeURIComponent(payload)).buffer;
  };
  window.KusunokiPdfDataUrlToArrayBuffer = dataUrlToArrayBuffer;
})();
